/* Derived tokens are declared on `*`, not `:root`, and that is load-bearing
   for the same reason as above: on :root they would freeze at the document
   root, so a Theme that sets --scaling or --radius-factor further down would
   change nothing. On `*` every element recomputes them from what it
   inherits, which is what makes scoping work. */
* {
  /* Radius steps — the base scale multiplied by the factor. */
  --radius-sm: calc((var(--radius) - 4px) * var(--radius-factor));
  --radius-md: calc((var(--radius) - 2px) * var(--radius-factor));
  --radius-lg: calc(var(--radius) * var(--radius-factor));
  --radius-xl: calc((var(--radius) + 4px) * var(--radius-factor));

  /* Radius intent — what components actually use.

     --radius-full is 0 except under radius="full", where it is 9999px. So
     max(step, --radius-full) resolves to the step normally and to a pill at
     full — that is --radius-control.

     Fields and panels take the same shape with a ceiling wrapped around it:
     min(cap, --radius-full) is 0 normally and the cap at full, so they step
     up with the preset without ever reaching a pill. A fully round text
     field reads as a search pill in a form that is not one, and a fully
     round card stops looking like a container. */
  --radius-control: max(calc((var(--radius) - 2px) * var(--radius-factor)), var(--radius-full));
  --radius-field: max(
    calc((var(--radius) - 2px) * var(--radius-factor)),
    min(calc(var(--radius) * var(--radius-factor)), var(--radius-full))
  );
  --radius-panel: max(
    calc((var(--radius) + 4px) * var(--radius-factor)),
    min(calc((var(--radius) + 8px) * var(--radius-factor)), var(--radius-full))
  );

  /* Font roles, read from whichever faces the scope sets. */
  --font-heading: var(--font-sans);
  --font-prose: var(--font-sans);

  /* Spacing — one multiplier over every gap and pad in the kit. */
  --space-1: calc(0.25rem * var(--scaling));
  --space-2: calc(0.5rem * var(--scaling));
  --space-3: calc(0.75rem * var(--scaling));
  --space-4: calc(1rem * var(--scaling));
  --space-6: calc(1.5rem * var(--scaling));
  --space-8: calc(2rem * var(--scaling));
  --space-10: calc(2.5rem * var(--scaling));
  --space-12: calc(3rem * var(--scaling));
  --space-1-5: calc(0.375rem * var(--scaling));
  --space-2-5: calc(0.625rem * var(--scaling));

  /* Control heights — one scale for every button, field, tab and row. */
  --control-sm: calc(1.5rem * var(--scaling));
  --control-md: calc(2rem * var(--scaling));

  /* Type roles. Leading is a ratio, so it follows the size under --scaling. */
  --text-heading-2xl: calc(2rem * var(--scaling));
  --text-heading-xl: calc(1.75rem * var(--scaling));
  --text-heading-lg: calc(1.5rem * var(--scaling));
  --text-heading-md: calc(1.25rem * var(--scaling));
  --text-heading-sm: calc(1rem * var(--scaling));
  --text-heading-xs: calc(0.875rem * var(--scaling));
  --text-heading-2xs: calc(0.75rem * var(--scaling));
  --text-body-lg: calc(1rem * var(--scaling));
  --text-body: calc(0.875rem * var(--scaling));
  --text-body-sm: calc(0.8125rem * var(--scaling));
  --text-body-xs: calc(0.625rem * var(--scaling));

  --leading-heading-2xl: calc(36 / 32);
  --leading-heading-xl: calc(32 / 28);
  --leading-heading-lg: calc(28 / 24);
  --leading-heading-md: calc(24 / 20);
  --leading-heading-sm: calc(20 / 16);
  --leading-heading-xs: calc(20 / 14);
  --leading-heading-2xs: calc(16 / 12);
  --leading-body-lg: calc(24 / 16);
  --leading-body: calc(20 / 14);
  --leading-body-sm: calc(16 / 13);
  --leading-body-xs: calc(14 / 10);

  /* Shadows read from the elevation tokens each appearance sets. */
  --shadow-none: var(--elevation-none);
  --shadow-2xs: var(--elevation-2xs);
  --shadow-xs: var(--elevation-xs);
  --shadow-sm: var(--elevation-sm);
  --shadow-md: var(--elevation-md);
  --shadow-lg: var(--elevation-lg);
  --shadow-xl: var(--elevation-xl);
  --shadow-2xl: var(--elevation-2xl);
}
